def hex_to_decimal(hex_str):
    return int(hex_str, 16)

hex_inputs = ["a7", "b3", "c9", "d5", "e1", "f8", "1a4", "1b9", "1c2", "1d7", "1e5", "1f3", "2a6", "2b1", "2c8", "2d4", "2e9", "2f5", "3a2", "3b7"]
decimal_outputs = [hex_to_decimal(hex_str) for hex_str in hex_inputs]

for i, decimal in enumerate(decimal_outputs, start=1):
    print(f"{i}. {decimal}")

def convert_hex_to_decimal(hex_num):
    return int(hex_num, 16)

# List of hexadecimal numbers
hex_numbers = ["a7", "b3", "c9", "d5", "e1", "f8", "1a4", "1b9", "1c2", "1d7", "1e5", "1f3", "2a6", "2b1", "2c8", "2d4", "2e9", "2f5", "3a2", "3b7"]

# Convert each hexadecimal number to decimal
decimal_numbers = [convert_hex_to_decimal(num) for num in hex_numbers]

# Print the results as a numbered list
for i, decimal in enumerate(decimal_numbers, start=1):
    print(f"{i}. {decimal}")

def rot13(word):
    result = ""
    for char in word:
        if char.isalpha():
            ascii_offset = 97 if char.islower() else 65
            result += chr((ord(char) - ascii_offset + 13) % 26 + ascii_offset)
        else:
            result += char
    return result

words = ["apple", "bridge", "candle", "dragon", "engine", "forest", "guitar", "hollow", "island", "jacket", "kitten", "ladder", "meadow", "needle", "orange", "pillow", "quiver", "rocket", "summer", "turtle"]

for i, word in enumerate(words, start=1):
    print(f"{i}. {rot13(word)}")
